export type BlockTypeValueType =
    | 'number'
    | 'text'
    | 'datetime'
    | 'boolean'
    | 'any';
export type BlockTypeCardinality = 'single' | 'rows';
export type BlockTypeFieldRole =
    | 'label'
    | 'value'
    | 'dimension'
    | 'measure'
    | 'time'
    | 'filter';
export type BlockTypeAggregation =
    | 'sum'
    | 'avg'
    | 'min'
    | 'max'
    | 'count'
    | 'first'
    | 'last';
export type BlockTypeHeight = 'small' | 'medium' | 'large';

export interface BlockTypeSlot {
    key: string;
    label: string;
    required: boolean;
    value_type: BlockTypeValueType;
    cardinality: BlockTypeCardinality;
    field_roles: BlockTypeFieldRole[];
}

export interface BlockTypeSize {
    default_width: number;
    min_width: number;
    max_width: number;
    default_height: BlockTypeHeight;
    min_height: BlockTypeHeight;
    max_height: BlockTypeHeight;
}

export interface BlockType {
    key: string;
    contract_version: number;
    title: string;
    slots: BlockTypeSlot[];
    size: BlockTypeSize;
    default_aggregations: Record<string, BlockTypeAggregation>;
}

